const $ = (selector, root = document) => root.querySelector(selector);
const state = { user: null, page: 'dashboard', data: null };
const cash = cents => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format((cents || 0) / 100);
const safe = value => String(value ?? '').replace(/[&<>"']/g, char => ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' })[char]);
const toast = message => { const node=$('#admin-toast');node.textContent=message;node.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>node.classList.remove('show'),3200); };
async function request(url, options = {}) { const response=await fetch(url,{...options,headers:{...(options.body?{'content-type':'application/json'}:{}),...(options.headers||{})}});const data=await response.json();if(!response.ok)throw new Error(data.error||'The request could not be completed.');return data; }
function addSomaliPaymentOptions(root=document){const labels={waafi:'WAAFI',edahab:'eDahab',sahal:'SAHAL',zaad:'ZAAD',somqr:'SOMQR / QR',premier_bank:'Premier Bank'};root.querySelectorAll('select[name="method"],#pos-payment').forEach(select=>{for(const [value,label] of Object.entries(labels)){if(!select.querySelector(`option[value="${value}"]`)){const option=document.createElement('option');option.value=value;option.textContent=label;select.append(option);}}});}
document.addEventListener('click',event=>{const row=event.target.closest('.row-action');if(row){state.currentOrderId=Number(row.dataset.order);setTimeout(()=>{const dialog=$('#order-detail');if(dialog)addSomaliPaymentOptions(dialog);},0);}});
document.addEventListener('click',event=>{const toggle=event.target.closest('[data-password-toggle]');if(!toggle)return;const input=document.getElementById(toggle.dataset.passwordToggle);if(!input)return;const show=input.type==='password';input.type=show?'text':'password';toggle.setAttribute('aria-pressed',String(show));toggle.setAttribute('aria-label',show?'Hide password':'Show password');});
new MutationObserver(records=>records.forEach(record=>{const page=record.target.closest?.('#page-content');if(page){addSomaliPaymentOptions(page);if(state.page==='kitchen'){const heading=page.querySelector('.card-heading');if(heading&&!heading.querySelector('#print-kitchen')){const button=document.createElement('button');button.id='print-kitchen';button.className='outline';button.textContent='Print tickets';button.addEventListener('click',()=>window.print());heading.append(button);}}}for(const node of record.addedNodes){if(node.nodeType===1&&node.matches('.detail-dialog'))addSomaliPaymentOptions(node);}})).observe(document.body,{childList:true,subtree:true});
function renderAuth(setup) {
  $('#app-shell').hidden=true;$('#auth-screen').hidden=false;
  $('#auth-eyebrow').textContent=setup?'FIRST-TIME SETUP':'STAFF ACCESS';$('#auth-title').textContent=setup?'Set up your workspace.':'Welcome back.';
  $('#auth-description').textContent=setup?'Create the first administrator username and password. Keep them somewhere secure.':'Enter your staff username and password to open this workspace.';
  $('#name-field').hidden=!setup;$('#name-field input').required=setup;$('#email-field').hidden=!setup;$('#email-field input').required=setup;$('#auth-form [name="username"]').required=true;$('#auth-form [name="password"]').minLength=setup?8:1;$('#auth-form [name="password"]').autocomplete=setup?'new-password':'current-password';$('#auth-submit').innerHTML=setup?'Create admin account <span>→</span>':'Sign in <span>→</span>';$('#forgot-login').hidden=setup;state.setup=setup;
}
async function boot() { try { const data=await request('/api/auth/me');if(data.user)await request('/api/auth/logout',{method:'POST'});renderAuth(data.needsSetup);}catch{renderAuth(false);} }
const authForm=$('#auth-form');
authForm.addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;const values=Object.fromEntries(new FormData(form).entries());const button=$('#auth-submit');button.disabled=true;$('#auth-error').textContent='';try{await request(state.setup?'/api/auth/setup':'/api/auth/login',{method:'POST',body:JSON.stringify(values)});const data=await request('/api/auth/me');state.user=data.user;form.reset();openApp();}catch(error){$('#auth-error').textContent=error.message;}finally{button.disabled=false;}});
$('#forgot-login').addEventListener('click',()=>$('#forgot-dialog').showModal());
function openApp(){ $('#auth-screen').hidden=true;$('#app-shell').hidden=false;document.body.classList.toggle('role-cashier',state.user.role==='cashier');$('#user-name').textContent=state.user.name;$('#user-role').textContent=state.user.role.replace('_',' ');$('#user-avatar').textContent=state.user.name.trim().slice(0,1).toUpperCase();const access={admin:['dashboard','pos','tables','orders','kitchen','menu','inventory','purchasing','reservations','customers','staff','partners','expenses','reports','audit','settings'],cashier:['dashboard','pos','tables','orders','menu','reservations','customers'],storekeeper:['inventory','purchasing'],delivery:['orders'],kitchen:['kitchen']};const pages=access[state.user.role]||[];$('#side-nav').querySelectorAll('[data-page]').forEach(button=>button.hidden=!pages.includes(button.dataset.page));state.page=({admin:'dashboard',cashier:'pos',storekeeper:'inventory',delivery:'orders',kitchen:'kitchen'})[state.user.role]||'dashboard';updateClock();setInterval(updateClock,30000);setInterval(()=>{if(state.user&&['kitchen','delivery'].includes(state.user.role)&&!document.hidden)showPage(state.page);},15000);showPage(state.page); }
function updateClock(){const now=new Date(new Date().toLocaleString('en-US',{timeZone:'Africa/Mogadishu'}));$('#today-date').textContent=new Intl.DateTimeFormat('en',{weekday:'long',day:'numeric',month:'long',timeZone:'Africa/Mogadishu'}).format(now);$('#live-clock').textContent=new Intl.DateTimeFormat('en',{hour:'2-digit',minute:'2-digit',timeZone:'Africa/Mogadishu'}).format(now);}
$('#signout').addEventListener('click',async()=>{await request('/api/auth/logout',{method:'POST'});state.user=null;renderAuth(false);});
$('#side-nav').addEventListener('click',event=>{const button=event.target.closest('[data-page]');if(!button)return;showPage(button.dataset.page);$('#side-nav').classList.remove('mobile-open');});
$('#mobile-nav').addEventListener('click',()=>$('#side-nav').classList.toggle('mobile-open'));
async function showPage(page){state.page=page;$('#side-nav').querySelectorAll('[data-page]').forEach(button=>button.classList.toggle('active',button.dataset.page===page));const title={dashboard:'Good day.',pos:'Point of sale',tables:'Tables',orders:'Orders',kitchen:'Kitchen display',menu:'Menu & dishes',inventory:'Inventory',purchasing:'Purchasing',reservations:'Reservations',customers:'Customers',staff:'Staff',partners:'Delivery partners',expenses:'Expenses',reports:'Reports',audit:'Audit log',settings:'Settings'}[page]||'Hodman';$('#page-title').textContent=title;$('#page-content').innerHTML='<div class="loading-state">Loading…</div>';try{if(page==='dashboard')await dashboard();else if(page==='pos')await pos();else if(page==='tables')await tables();else if(page==='orders'||page==='kitchen')await orders(page==='kitchen');else if(page==='menu')await menu();else if(page==='inventory')await inventory();else if(page==='purchasing')await purchasing();else if(page==='reservations')await reservations();else if(page==='customers')await customers();else if(page==='staff')await staff();else if(page==='partners')await partners();else if(page==='expenses')await expenses();else if(page==='reports')await reports();else if(page==='audit')await auditPage();else if(page==='settings')await settings();}catch(error){$('#page-content').innerHTML=`<div class="error-panel"><strong>Could not load this page</strong><p>${safe(error.message)}</p><button class="outline" onclick="location.reload()">Reload workspace</button></div>`;}}
async function dashboard(){const d=await request('/api/admin/summary');state.data=d;$('#page-content').innerHTML=`<section class="welcome-row"><div><p class="muted">Here’s what’s happening at Hodman today.</p></div><button class="primary" data-go="orders">View active orders <span>→</span></button></section><div class="metric-grid"><article class="metric-card"><span class="metric-icon navy">▤</span><div><small>ORDERS TODAY</small><strong>${d.todayOrders}</strong></div><span class="metric-foot">All order types</span></article><article class="metric-card"><span class="metric-icon gold">$</span><div><small>SALES TODAY</small><strong>${cash(d.todaySalesCents)}</strong></div><span class="metric-foot">Completed and active</span></article><article class="metric-card"><span class="metric-icon blue">◷</span><div><small>ACTIVE ORDERS</small><strong>${d.activeOrders}</strong></div><span class="metric-foot">Need attention</span></article><article class="metric-card"><span class="metric-icon green">▦</span><div><small>LOW STOCK ITEMS</small><strong>${d.lowStock}</strong></div><span class="metric-foot">At or below reorder level</span></article></div><section class="content-card"><div class="card-heading"><div><span class="eyebrow">SERVICE IN MOTION</span><h2>Recent orders</h2></div><button class="plain-link" data-go="orders">All orders →</button></div>${orderTable(d.latestOrders,true)}</section><section class="quick-grid"><button class="quick-card" data-go="menu"><span>◉</span><strong>Update the menu</strong><small>Add dishes and categories</small><b>→</b></button><button class="quick-card" data-go="inventory"><span>▦</span><strong>Check ingredients</strong><small>Stock levels and recipes</small><b>→</b></button><button class="quick-card" data-go="reservations"><span>▤</span><strong>Reservations</strong><small>${d.todayReservations} requests today</small><b>→</b></button></section>`;$('#page-content').querySelectorAll('[data-go]').forEach(button=>button.addEventListener('click',()=>showPage(button.dataset.go)));}
function statusLabel(status){return ({new:'New',confirmed:'Confirmed',preparing:'Preparing',ready:'Ready',out_for_delivery:'On the way',completed:'Completed',cancelled:'Cancelled'})[status]||status;}
function orderTable(orders,compact=false){if(!orders?.length)return '<div class="empty-state"><span>♡</span><strong>No orders yet</strong><p>New orders will appear here as soon as customers place them.</p></div>';return `<div class="table-wrap"><table><thead><tr><th>ORDER</th><th>CUSTOMER</th><th>TYPE</th><th>STATUS</th><th>TOTAL</th>${compact?'':'<th>PAYMENT</th>'}<th></th></tr></thead><tbody>${orders.map(o=>`<tr><td><strong class="order-ref">${safe(o.order_number)}</strong><small>${new Date(o.created_at+'Z').toLocaleString('en',{hour:'2-digit',minute:'2-digit',day:'numeric',month:'short'})}</small></td><td>${safe(o.customer_name)}</td><td><span class="type-label">${safe(o.order_type.replace('-',' '))}</span></td><td><span class="status-pill ${safe(o.status)}">${safe(statusLabel(o.status))}</span></td><td class="amount">${cash(o.total_cents)}</td>${compact?'':`<td><span class="payment-label ${safe(o.payment_status)}">${safe(o.payment_status.replace('_',' '))}</span></td>`}<td>${state.user.role==='delivery'?((o.status==='ready'||o.status==='out_for_delivery')?`<button class="outline mini" data-driver-status="${o.id}" data-next="${o.status==='ready'?'out_for_delivery':'completed'}">${o.status==='ready'?'Start delivery':'Mark delivered'}</button> `:'<span class="status-pill preparing">Waiting for kitchen</span> '):''}<button class="row-action" data-order="${o.id}" title="Open order">›</button></td></tr>`).join('')}</tbody></table></div>`;}
async function orders(kitchen=false){const d=await request('/api/admin/orders');const list=state.user.role==='kitchen'?d.orders.filter(o=>!['completed','cancelled'].includes(o.status)):d.orders;$('#page-content').innerHTML=`<section class="welcome-row"><p class="muted">${kitchen?'Incoming tickets, ready to prepare.':(state.user.role==='delivery'?'Orders assigned to you. Waiting orders appear now; start delivery when the kitchen marks them Ready.':'Manage incoming orders and record payments.')}</p>${!kitchen&&['admin','cashier'].includes(state.user.role)?'<button class="outline" data-refresh>↻ Refresh</button>':''}</section><section class="content-card">${list.length?`<div class="card-heading"><div><span class="eyebrow">${kitchen?'LIVE KITCHEN QUEUE':'ORDER MANAGEMENT'}</span><h2>${kitchen?'Kitchen tickets':'Recent orders'}</h2></div><span class="result-count">${list.length} orders</span></div>${kitchen?`<div class="ticket-grid">${list.map(o=>ticket(o)).join('')}</div>`:orderTable(list)}`:state.user.role==='delivery'?'<div class="empty-state"><span>➜</span><strong>No assigned deliveries</strong><p>Ask the administrator to assign a delivery order to your account.</p></div>':'<div class="empty-state"><span>♡</span><strong>No active orders</strong><p>Orders will show up here as customers place them.</p></div>'}</section>`;$('#page-content').querySelector('[data-refresh]')?.addEventListener('click',()=>showPage(state.page));if(!kitchen)$('#page-content').querySelectorAll('[data-order]').forEach(button=>button.addEventListener('click',()=>orderDetail(list.find(row=>row.id===Number(button.dataset.order)))));if(kitchen)$('#page-content').querySelectorAll('[data-next]').forEach(button=>button.addEventListener('click',()=>changeStatus(Number(button.dataset.id),button.dataset.next)));if(state.user.role==='delivery')$('#page-content').querySelectorAll('[data-driver-status]').forEach(button=>button.addEventListener('click',()=>changeStatus(Number(button.dataset.driverStatus),button.dataset.next)));}
function ticket(order){return `<article class="ticket"><header><strong>${safe(order.order_number)}</strong><span class="status-pill ${safe(order.status)}">${safe(statusLabel(order.status))}</span></header><div class="ticket-meta">${safe(order.order_type.replace('-',' '))} · ${new Date(order.created_at+'Z').toLocaleTimeString('en',{hour:'2-digit',minute:'2-digit'})}<br>${safe(order.customer_name)} · ${safe(order.customer_phone)}</div><ul>${safe(order.items||'').split(', ').map(item=>`<li>${item}</li>`).join('')}</ul>${order.notes?`<p class="ticket-notes">Note: ${safe(order.notes)}</p>`:''}<div class="ticket-footer"><span>${safe(order.payment_status.replace('_',' '))}</span>${nextStatus(order.status)?`<button class="primary compact" data-id="${order.id}" data-next="${nextStatus(order.status)}">${nextLabel(order.status)} →</button>`:''}</div></article>`;}
async function pos(){if(!['admin','cashier'].includes(state.user.role))throw new Error('Your role cannot use point of sale.');const [menuData,tableData]=await Promise.all([request('/api/admin/menu'),request('/api/admin/tables')]);const cart=new Map();$('#page-content').innerHTML=`<section class="welcome-row"><p class="muted">Build a sale. Prices are calculated from the current menu.</p><span class="result-count">USD · ${menuData.products.length} dishes</span></section><div class="pos-layout"><section class="pos-products"><div class="pos-search"><input id="pos-search" placeholder="Search dishes…" aria-label="Search dishes"><select id="pos-category"><option value="">All categories</option>${menuData.categories.map(c=>`<option value="${c.id}">${safe(c.name)}</option>`).join('')}</select></div><div class="pos-product-grid" id="pos-product-grid"></div></section><section class="content-card pos-checkout"><span class="eyebrow">NEW SALE</span><h2>Build an order</h2><div class="pos-field"><label>Order type</label><select id="pos-type"><option value="dine-in">Dine in</option><option value="takeaway">Takeaway</option><option value="delivery">Delivery</option></select></div><div class="pos-field" id="pos-table-field"><label>Available table</label><select id="pos-table"><option value="">Choose table</option>${tableData.tables.filter(t=>t.status==='available').map(t=>`<option value="${t.id}">${safe(t.table_name)} · ${t.capacity} seats${t.section?' · '+safe(t.section):''}</option>`).join('')}</select>${!tableData.tables.length?'<small>Add restaurant tables in the Tables section first.</small>':''}</div><div class="pos-customer"><label>Customer name<input id="pos-customer-name" value="Guest" maxlength="100"></label><label>Phone (optional)<input id="pos-customer-phone" placeholder="Walk-in" maxlength="40"></label></div><div class="pos-cart" id="pos-cart"><div class="pos-empty">Choose dishes to begin</div></div><div class="pos-total"><span>Order total</span><strong id="pos-total">$0.00</strong></div><div class="pos-field"><label>Payment at counter</label><select id="pos-payment"><option value="unpaid">Record payment later</option><option value="cash">Cash</option><option value="evc_plus">EVC-Plus</option><option value="card">Card</option><option value="bank_transfer">Bank transfer</option></select></div><button class="primary wide" id="pos-submit" disabled>Create order <span>→</span></button></section></div>`;addSomaliPaymentOptions($('#page-content'));const drawProducts=()=>{const query=$('#pos-search').value.toLowerCase(),category=$('#pos-category').value,products=menuData.products.filter(p=>p.available&&(!category||String(p.category_id)===category)&&`${p.name} ${p.description}`.toLowerCase().includes(query));$('#pos-product-grid').innerHTML=products.length?products.map(p=>`<button class="pos-product" data-product="${p.id}"><span class="dish-art">♡</span><strong>${safe(p.name)}</strong><small>${safe(p.category_name||'Uncategorized')}</small><b>${cash(p.price_cents)}</b></button>`).join(''):'<div class="empty-state"><span>◉</span><strong>No dishes found</strong><p>Publish dishes in Menu & dishes before opening a sale.</p></div>';$('#pos-product-grid').querySelectorAll('[data-product]').forEach(button=>button.addEventListener('click',()=>{const p=menuData.products.find(item=>item.id===Number(button.dataset.product)),row=cart.get(p.id)||{id:p.id,name:p.name,price:p.price_cents,quantity:0};row.quantity++;cart.set(p.id,row);drawCart();}));};const drawCart=()=>{const items=[...cart.values()];$('#pos-cart').innerHTML=items.length?items.map(item=>`<div class="pos-cart-item"><div><strong>${safe(item.name)}</strong><small>${cash(item.price)}</small></div><div class="quantity-stepper"><button data-change="-1" data-id="${item.id}">−</button><span>${item.quantity}</span><button data-change="1" data-id="${item.id}">+</button></div></div>`).join(''):'<div class="pos-empty">Choose dishes to begin</div>';for(const button of $('#pos-cart').querySelectorAll('[data-change]'))button.addEventListener('click',()=>{const item=cart.get(Number(button.dataset.id));item.quantity+=Number(button.dataset.change);if(item.quantity<=0)cart.delete(item.id);drawCart();});const total=items.reduce((sum,item)=>sum+item.price*item.quantity,0);$('#pos-total').textContent=cash(total);$('#pos-submit').disabled=!items.length;};$('#pos-search').addEventListener('input',drawProducts);$('#pos-category').addEventListener('change',drawProducts);$('#pos-type').addEventListener('change',()=>{$('#pos-table-field').hidden=$('#pos-type').value!=='dine-in';});$('#pos-submit').addEventListener('click',async()=>{const items=[...cart.values()],method=$('#pos-payment').value,payload={orderType:$('#pos-type').value,tableId:$('#pos-table').value||null,customerName:$('#pos-customer-name').value.trim()||'Guest',phone:$('#pos-customer-phone').value.trim()||'Walk-in',items:items.map(({id,quantity})=>({productId:id,quantity})),payments:[]};if(method!=='unpaid')payload.payments=[{method,amount:items.reduce((sum,item)=>sum+item.price*item.quantity,0)/100}];const button=$('#pos-submit');button.disabled=true;try{const result=await request('/api/admin/pos/orders',{method:'POST',body:JSON.stringify(payload)});toast(`Order ${result.orderNumber} created.`);showPage('pos');}catch(error){toast(error.message);button.disabled=false;}});drawProducts();}
async function tables(){
  if(!['admin','cashier','delivery'].includes(state.user.role))throw new Error('Your role cannot view tables.');
  const d=await request('/api/admin/tables');
  const cards=d.tables.map(t=>{
    const statusClass=t.status==='available'?'available':t.status==='occupied'?'preparing':t.status==='cleaning'?'new':'cancelled';
    const choices=t.status==='cleaning'?['available','out_of_service']:t.status==='available'?['reserved','out_of_service']:['available','cleaning','out_of_service'];
    const controls=['admin','cashier'].includes(state.user.role)&&t.status!=='occupied'?`<select data-table-status="${t.id}"><option value="">Update status</option>${choices.map(s=>`<option value="${s}">${s.replace('_',' ')}</option>`).join('')}</select>`:'';
    return `<article class="restaurant-table ${safe(t.status)}"><span class="table-status-dot"></span><strong>${safe(t.table_name)}</strong><small>${t.capacity} seats${t.section?' · '+safe(t.section):''}</small><span class="status-pill ${statusClass}">${safe(t.status.replace('_',' '))}</span>${controls}</article>`;
  }).join('');
  const tableContent=cards?`<div class="table-cards">${cards}</div>`:`<section class="content-card"><div class="empty-state"><span>▦</span><strong>No tables added</strong><p>Create your table list to start dine-in sales.</p>${state.user.role==='admin'?'<button class="primary" id="empty-table">Add first table →</button>':''}</div></section>`;
  $('#page-content').innerHTML=`<section class="welcome-row"><p class="muted">See the dining room at a glance. Completed bills move tables into cleaning.</p>${state.user.role==='admin'?'<button class="primary" id="add-table">+ Add table <span>→</span></button>':''}</section>${tableContent}`;
  $('#add-table')?.addEventListener('click',tableForm);$('#empty-table')?.addEventListener('click',tableForm);
  $('#page-content').querySelectorAll('[data-table-status]').forEach(select=>select.addEventListener('change',async()=>{if(!select.value)return;try{await request(`/api/admin/tables/${select.dataset.tableStatus}/status`,{method:'PATCH',body:JSON.stringify({status:select.value})});toast('Table status updated.');showPage('tables');}catch(error){toast(error.message);}}));
}
function tableForm(){const name=prompt('Table name or number');if(!name?.trim())return;const capacity=Number(prompt('Number of seats','4'));if(!capacity)return;const section=prompt('Room or section (optional)')||'';request('/api/admin/tables',{method:'POST',body:JSON.stringify({name,capacity,section})}).then(()=>{toast('Table added.');showPage('tables');}).catch(error=>toast(error.message));}
function nextStatus(status){return ({new:'confirmed',confirmed:'preparing',preparing:'ready',ready:'completed',out_for_delivery:'completed'})[status]||'';}
function nextLabel(status){return ({new:'Confirm',confirmed:'Start',preparing:'Ready',ready:'Complete',out_for_delivery:'Delivered'})[status]||'Update';}
async function changeStatus(id,status){try{await request(`/api/admin/orders/${id}/status`,{method:'PATCH',body:JSON.stringify({status})});toast(`Order moved to ${statusLabel(status).toLowerCase()}.`);showPage(state.page);}catch(e){toast(e.message);}}
function orderDetail(order){
  const el=$('#order-detail');el?.remove();
  const canManage=['admin','cashier'].includes(state.user.role);const detailNext=state.user.role==='delivery'?(order.status==='ready'?'out_for_delivery':order.status==='out_for_delivery'?'completed':''):nextStatus(order.status);const detailNextLabel=state.user.role==='delivery'?(order.status==='ready'?'Start delivery':'Mark delivered'):nextLabel(order.status);
  const deliveryControls=order.order_type==='delivery'&&canManage?`<section class="delivery-routing"><div class="delivery-routing-heading"><span class="eyebrow">DELIVERY ASSIGNMENT</span><p>Choose the exact driver or approved partner for this order.</p></div><div class="delivery-routing-options"><div class="delivery-route-option"><label for="hodman-driver-choice">Hodman delivery staff</label><select id="hodman-driver-choice"><option value="">Loading drivers…</option></select><button class="outline" type="button" id="assign-hodman-driver">Assign Hodman delivery staff</button></div><div class="delivery-route-option"><label for="partner-choice">Approved outside partner</label><select id="partner-choice"><option value="">Loading partners…</option></select><button class="outline" type="button" id="assign-outside-partner">Assign outside delivery partner</button></div></div><p class="delivery-routing-note">The assigned delivery account sees it now and can accept the delivery once it is Ready.</p></section>`:'';
  const dlg=document.createElement('dialog');dlg.id='order-detail';dlg.className='detail-dialog';
  dlg.innerHTML=`<div class="dialog-heading"><div><span class="eyebrow">ORDER DETAILS</span><h2>${safe(order.order_number)}</h2></div><button class="close-dialog">×</button></div><p class="detail-meta">${safe(order.customer_name)} · ${safe(order.customer_phone)} · ${safe(order.order_type)}${order.delivery_address?' · '+safe(order.delivery_address):''}</p><ul class="detail-items">${safe(order.items||'').split(', ').map(i=>`<li>${i}</li>`).join('')}</ul><p class="detail-total">Order total <strong>${cash(order.total_cents)}</strong></p><p class="detail-meta">Payment status: <b>${safe(order.payment_status)}</b></p>${deliveryControls}${canManage&&!['paid','refunded'].includes(order.payment_status)?`<form id="payment-form" class="payment-form"><label>Amount (USD)<input name="amount" type="number" min="0.01" step="0.01" max="${(order.total_cents/100).toFixed(2)}" value="${(order.total_cents/100).toFixed(2)}" required></label><label>Method<select name="method"><option value="evc_plus">EVC-Plus</option><option value="cash">Cash</option><option value="card">Card</option><option value="bank_transfer">Bank transfer</option><option value="other">Other</option></select></label><label class="wide-label">Payment reference (optional)<input name="reference"></label><button class="primary wide-label">Record payment →</button></form>`:''}<div class="dialog-actions">${detailNext?`<button class="primary" data-status="${detailNext}">${detailNextLabel} →</button>`:''}<button class="outline close-dialog">Close</button></div>`;
  document.body.append(dlg);dlg.showModal();dlg.querySelectorAll('.close-dialog').forEach(b=>b.addEventListener('click',()=>dlg.close()));
  dlg.querySelector('[data-status]')?.addEventListener('click',async e=>{await changeStatus(order.id,e.currentTarget.dataset.status);dlg.close();});
  dlg.querySelector('#payment-form')?.addEventListener('submit',async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.currentTarget).entries());try{await request(`/api/admin/orders/${order.id}/payments`,{method:'POST',body:JSON.stringify(v)});toast('Payment recorded.');dlg.close();showPage('orders');}catch(err){toast(err.message);}});
  const driverChoice=dlg.querySelector('#hodman-driver-choice'),partnerChoice=dlg.querySelector('#partner-choice');
  if(driverChoice&&partnerChoice){Promise.all([request('/api/admin/delivery-staff'),request('/api/admin/delivery-partners')]).then(([staffData,partnerData])=>{driverChoice.innerHTML=staffData.staff.length?'<option value="">Choose a Hodman driver</option>'+staffData.staff.map(person=>`<option value="${person.id}">${safe(person.name)}</option>`).join(''):'<option value="">No active delivery staff</option>';partnerChoice.innerHTML=partnerData.partners.length?'<option value="">Choose an approved partner</option>'+partnerData.partners.map(partner=>`<option value="${partner.id}">${safe(partner.business_name)} · ${safe(partner.contact_name)}</option>`).join(''):'<option value="">No approved partners</option>';}).catch(error=>{driverChoice.innerHTML='<option value="">Could not load drivers</option>';partnerChoice.innerHTML='<option value="">Could not load partners</option>';toast(error.message);});
    dlg.querySelector('#assign-hodman-driver').addEventListener('click',async e=>{const button=e.currentTarget,staffId=Number(driverChoice.value);if(!staffId)return toast('Choose an active Hodman delivery staff member first.');button.disabled=true;try{await request(`/api/admin/orders/${order.id}/assign-driver`,{method:'POST',body:JSON.stringify({staffId})});toast('Order assigned to '+driverChoice.selectedOptions[0].text+'.');dlg.close();showPage('orders');}catch(error){toast(error.message);}finally{button.disabled=false;}});
    dlg.querySelector('#assign-outside-partner').addEventListener('click',async e=>{const button=e.currentTarget,partnerId=Number(partnerChoice.value);if(!partnerId)return toast('Choose an approved outside delivery partner first.');button.disabled=true;try{const result=await request(`/api/admin/orders/${order.id}/assign-partner`,{method:'POST',body:JSON.stringify({partnerId})});toast(`Order assigned to ${result.partnerName}.`);dlg.close();showPage('orders');}catch(error){toast(error.message);}finally{button.disabled=false;}});
  }
  dlg.addEventListener('close',()=>dlg.remove());
}
async function menu() {
  if (!['admin', 'cashier'].includes(state.user.role)) throw new Error('Your role cannot manage menu items.');
  const d = await request('/api/admin/menu');
  state.data = d;
  const admin = state.user.role === 'admin';
  $('#page-content').innerHTML = `<section class="welcome-row"><p class="muted">Keep your dishes and prices up to date for customers.</p>${admin ? `<div class="button-group"><button class="outline" id="add-category">+ Category</button><button class="primary" id="add-product">+ Add a dish <span>→</span></button></div>` : ''}</section><section class="content-card"><div class="card-heading"><div><span class="eyebrow">CUSTOMER MENU</span><h2>Dishes & availability</h2></div><span class="result-count">${d.products.length} dishes</span></div>${d.products.length ? `<div class="menu-list">${d.products.map(p => `<article class="menu-row"><span class="dish-art">♡</span><div class="dish-info"><strong>${safe(p.name)}</strong><small>${safe(p.category_name || 'Uncategorized')} · ${safe(p.description || 'No description')}</small></div><strong class="amount">${cash(p.price_cents)}</strong><span class="status-pill ${p.available ? 'available' : 'cancelled'}">${p.available ? 'Available' : 'Hidden'}</span>${admin ? `<div class="menu-actions"><button class="outline mini" data-toggle="${p.id}" data-value="${p.available ? '0' : '1'}">${p.available ? 'Hide' : 'Publish'}</button><button class="outline mini" data-edit="${p.id}">Edit</button></div>` : ''}</article>`).join('')}</div>` : `<div class="empty-state"><span>♡</span><strong>Your menu starts here</strong><p>Add menu categories and dishes to publish them on the website.</p>${admin ? '<button class="primary" id="empty-product">Add your first dish →</button>' : ''}</div>`}</section><div class="content-card tip-card"><span>✦</span><p>Customers see published dishes and live prices on the Hodman website. Keep stock availability in sync with the kitchen.</p></div>`;
  if (!admin) return;
  $('#add-category').addEventListener('click', categoryForm);
  $('#add-product').addEventListener('click', () => productForm(d.categories));
  $('#empty-product')?.addEventListener('click', () => productForm(d.categories));
  $('#page-content').querySelectorAll('[data-toggle]').forEach(button => button.addEventListener('click', async () => {
    try { await request(`/api/admin/products/${button.dataset.toggle}/availability`, { method: 'PATCH', body: JSON.stringify({ available: button.dataset.value === '1' }) }); toast('Menu availability updated.'); showPage('menu'); }
    catch (error) { toast(error.message); }
  }));
  $('#page-content').querySelectorAll('[data-edit]').forEach(button => button.addEventListener('click', () => productEditForm(d.products.find(product => product.id === Number(button.dataset.edit)), d.categories)));
}
function categoryForm(){const modal=dialogForm('Add a menu category',`<label>Category name<input name="name" required minlength="2" maxlength="60" placeholder="For example, Main dishes"></label><label class="wide-label">Description <span class="form-hint">Optional</span><textarea name="description" rows="3" maxlength="250" placeholder="A short description for customers"></textarea></label><button class="primary wide-label" type="submit">Save category →</button>`);modal.querySelector('form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('[type="submit"]'),values=Object.fromEntries(new FormData(form).entries());button.disabled=true;try{await request('/api/admin/categories',{method:'POST',body:JSON.stringify(values)});toast('Category added.');modal.close();showPage('menu');}catch(error){toast(error.message);button.disabled=false;}});}
function productEditForm(product,categories){if(!product)return toast('This dish is no longer available.');const options=`<option value="" ${product.category_id==null?'selected':''}>No category</option>${categories.map(c=>`<option value="${c.id}" ${Number(c.id)===Number(product.category_id)?'selected':''}>${safe(c.name)}</option>`).join('')}`;const modal=dialogForm('Edit dish',`<label>Dish name<input name="name" value="${safe(product.name)}" required minlength="2" maxlength="100"></label><label>Price in USD<input name="price" type="number" min="0" step="0.01" value="${(product.price_cents/100).toFixed(2)}" required></label><label>Category<select name="categoryId">${options}</select></label><label>Image URL (optional)<input name="imageUrl" type="url" maxlength="400" value="${safe(product.image_url||'')}"></label><label class="wide-label">Description<textarea name="description" rows="3" maxlength="500">${safe(product.description||'')}</textarea></label><button class="primary wide-label" type="submit">Save dish changes →</button>`);const form=modal.querySelector('form');form.addEventListener('submit',async event=>{event.preventDefault();const values=Object.fromEntries(new FormData(form).entries()),button=form.querySelector('[type="submit"]');button.disabled=true;try{await request(`/api/admin/products/${product.id}`,{method:'PATCH',body:JSON.stringify(values)});toast('Dish updated.');modal.close();showPage('menu');}catch(error){toast(error.message);button.disabled=false;}});}
function productForm(categories){const modal=dialogForm('Add a dish',`<label>Dish name<input name="name" required minlength="2"></label><label>Price in USD<input name="price" type="number" min="0" step="0.01" required></label><label>Category<select name="categoryId"><option value="">No category</option>${categories.map(c=>`<option value="${c.id}">${safe(c.name)}</option>`).join('')}</select></label><label>Image URL (optional)<input name="imageUrl" type="url"></label><label class="wide-label">Description<textarea name="description" rows="3"></textarea></label><button class="primary wide-label">Save dish →</button>`);modal.querySelector('form').addEventListener('submit',async event=>{event.preventDefault();const values=Object.fromEntries(new FormData(event.currentTarget).entries());try{await request('/api/admin/products',{method:'POST',body:JSON.stringify(values)});toast('Dish added to the menu.');modal.close();showPage('menu');}catch(error){toast(error.message);}});}
function dialogForm(title,fields){const dialog=document.createElement('dialog');dialog.className='detail-dialog';dialog.innerHTML=`<div class="dialog-heading"><div><span class="eyebrow">MENU MANAGEMENT</span><h2>${title}</h2></div><button class="close-dialog">×</button></div><form class="form-grid">${fields}</form>`;document.body.append(dialog);dialog.showModal();dialog.querySelectorAll('.close-dialog').forEach(button=>button.addEventListener('click',()=>dialog.close()));dialog.addEventListener('close',()=>dialog.remove());return dialog;}
async function inventory(){if(!['admin','storekeeper'].includes(state.user.role))throw new Error('Your role cannot manage inventory.');const d=await request('/api/admin/inventory');$('#page-content').innerHTML=`<section class="welcome-row"><p class="muted">Track ingredients, stock levels, and the recipes behind your dishes.</p><button class="primary" id="add-ingredient">+ Add ingredient <span>→</span></button></section><section class="content-card"><div class="card-heading"><div><span class="eyebrow">ON HAND</span><h2>Ingredients & stock</h2></div><button class="outline" id="adjust-stock">Adjust stock</button></div>${d.ingredients.length?`<div class="table-wrap"><table><thead><tr><th>INGREDIENT</th><th>ON HAND</th><th>REORDER AT</th><th>STATUS</th></tr></thead><tbody>${d.ingredients.map(i=>`<tr><td><strong>${safe(i.name)}</strong></td><td>${i.stock_quantity} ${safe(i.unit)}</td><td>${i.reorder_level} ${safe(i.unit)}</td><td><span class="status-pill ${i.stock_quantity<=i.reorder_level?'cancelled':'available'}">${i.stock_quantity<=i.reorder_level?'Low stock':'In stock'}</span></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state"><span>▦</span><strong>No ingredients yet</strong><p>Add stock items, set reorder levels, then connect each dish to its recipe.</p><button class="primary" id="empty-ingredient">Add first ingredient →</button></div>'}</section><section class="content-card"><div class="card-heading"><div><span class="eyebrow">KITCHEN RECIPES</span><h2>Dish recipes</h2></div><button class="outline" id="set-recipe">Set a recipe</button></div>${d.recipes.length?`<div class="table-wrap"><table><thead><tr><th>DISH</th><th>INGREDIENT</th><th>RECIPE QUANTITY</th></tr></thead><tbody>${d.recipes.map(r=>`<tr><td>${safe(r.product_name)}</td><td>${safe(r.ingredient_name)}</td><td>${r.quantity} ${safe(r.unit)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted section-pad">Add recipes to calculate stock usage from sold dishes.</p>'}</section>`;$('#add-ingredient').addEventListener('click',()=>ingredientForm());$('#empty-ingredient')?.addEventListener('click',()=>ingredientForm());$('#adjust-stock').addEventListener('click',()=>adjustmentForm(d.ingredients));$('#set-recipe').addEventListener('click',()=>recipeForm(d.products,d.ingredients));}
function ingredientForm(){const d=dialogForm('Add an ingredient',`<label>Name<input name="name" required></label><label>Unit<input name="unit" required placeholder="kg, piece, litre"></label><label>Opening stock<input name="quantity" type="number" min="0" step="0.001" value="0" required></label><label>Reorder level<input name="reorderLevel" type="number" min="0" step="0.001" value="0"></label><button class="primary wide-label">Save ingredient →</button>`);d.querySelector('form').addEventListener('submit',async e=>{e.preventDefault();try{await request('/api/admin/inventory/ingredients',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget).entries()))});toast('Ingredient added.');d.close();showPage('inventory');}catch(err){toast(err.message);}});}
function adjustmentForm(items){if(!items.length)return toast('Add an ingredient before adjusting stock.');const d=dialogForm('Adjust stock',`<label>Ingredient<select name="ingredientId">${items.map(i=>`<option value="${i.id}">${safe(i.name)} (${i.stock_quantity} ${safe(i.unit)})</option>`).join('')}</select></label><label>Change quantity<input name="quantity" type="number" step="0.001" required placeholder="Use negative for waste"></label><label class="wide-label">Reason<input name="reason" required placeholder="Purchase, waste, stock count…"></label><button class="primary wide-label">Save adjustment →</button>`);d.querySelector('form').addEventListener('submit',async e=>{e.preventDefault();try{await request('/api/admin/inventory/adjustments',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget).entries()))});toast('Stock adjustment saved.');d.close();showPage('inventory');}catch(err){toast(err.message);}});}
function recipeForm(products,items){if(!products.length||!items.length)return toast('Add at least one dish and one ingredient first.');const options=items.map(i=>`<option value="${i.id}" data-unit="${safe(i.unit)}">${safe(i.name)} (${safe(i.unit)})</option>`).join('');const rows=[0,1,2].map((_,idx)=>`<div class="recipe-row"><select name="ingredient${idx}"><option value="">Choose ingredient (optional)</option>${options}</select><input name="quantity${idx}" type="number" min="0.001" step="0.001" placeholder="Amount"></div>`).join('');const d=dialogForm('Set a dish recipe',`<label class="wide-label">Dish<select name="productId">${products.map(p=>`<option value="${p.id}">${safe(p.name)}</option>`).join('')}</select></label><div class="wide-label recipe-list">${rows}<button type="button" id="more-ingredient" class="plain-link">+ Add another ingredient</button></div><button class="primary wide-label">Save recipe →</button>`);d.querySelector('#more-ingredient').addEventListener('click',()=>{const row=document.createElement('div');row.className='recipe-row';row.innerHTML=`<select><option value="">Choose ingredient</option>${options}</select><input type="number" min="0.001" step="0.001" placeholder="Amount">`;d.querySelector('.recipe-list').insertBefore(row,d.querySelector('#more-ingredient'));});d.querySelector('form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget),ingredients=[];e.currentTarget.querySelectorAll('.recipe-row').forEach(row=>{const select=row.querySelector('select'),quantity=row.querySelector('input');if(select.value&&quantity.value)ingredients.push({ingredientId:Number(select.value),quantity:Number(quantity.value)});});try{await request('/api/admin/inventory/recipes',{method:'PUT',body:JSON.stringify({productId:Number(f.get('productId')),ingredients})});toast('Recipe saved.');d.close();showPage('inventory');}catch(err){toast(err.message);}});}
async function reservations(){const d=await request('/api/admin/reservations');$('#page-content').innerHTML=`<section class="welcome-row"><p class="muted">Review guest requests and confirm directly with them.</p></section><section class="content-card"><div class="card-heading"><div><span class="eyebrow">GUEST BOOKINGS</span><h2>Reservation requests</h2></div><span class="result-count">${d.reservations.length} requests</span></div>${d.reservations.length?`<div class="table-wrap"><table><thead><tr><th>GUEST</th><th>PHONE</th><th>WHEN</th><th>GUESTS</th><th>STATUS</th><th>UPDATE</th></tr></thead><tbody>${d.reservations.map(r=>`<tr><td><strong>${safe(r.customer_name)}</strong>${r.notes?`<small>${safe(r.notes)}</small>`:''}</td><td><a href="tel:${safe(r.phone)}">${safe(r.phone)}</a></td><td>${new Date(r.reservation_at).toLocaleString('en',{dateStyle:'medium',timeStyle:'short'})}</td><td>${r.guests}</td><td><span class="status-pill ${r.status==='confirmed'?'available':r.status==='declined'?'cancelled':'new'}">${safe(r.status)}</span></td><td>${['requested','confirmed'].includes(r.status)?`<button class="outline mini" data-reservation="${r.id}" data-status="${r.status==='confirmed'?'completed':'confirmed'}">${r.status==='confirmed'?'Complete':'Confirm'}</button> <button class="outline mini" data-reservation="${r.id}" data-status="declined">Decline</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state"><span>▤</span><strong>No reservations yet</strong><p>Requests from the website will appear here.</p></div>'}</section>`;$('#page-content').querySelectorAll('[data-reservation]').forEach(button=>button.addEventListener('click',async()=>{try{await request(`/api/admin/reservations/${button.dataset.reservation}/status`,{method:'PATCH',body:JSON.stringify({status:button.dataset.status})});toast('Reservation updated.');showPage('reservations');}catch(e){toast(e.message);}}));}
function resetAccountPassword(button) {
  const kind=button.dataset.resetKind,id=button.dataset.resetId,name=button.dataset.resetName,login=button.dataset.resetLogin;
  const loginLabel=kind==='staff'?'Username':'Login email',route=kind==='staff'?`/api/admin/staff/${id}/password`:`/api/admin/partners/${id}/password`;
  const d=dialogForm('Set a new password',`<p class="form-hint wide-label">${safe(name)} signs in with ${safe(loginLabel.toLowerCase())}: <strong>${safe(login)}</strong>. The old password cannot be viewed. Set a new password to share with them.</p><label class="wide-label">New password<span class="password-control"><input id="account-reset-password" name="password" type="password" required minlength="8" maxlength="128" autocomplete="new-password"><button class="password-toggle" type="button" data-password-toggle="account-reset-password" aria-label="Show password" aria-pressed="false"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2 12s3.6-7 10-7 10 7 10 7-3.6 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/><path class="eye-slash" d="m3 3 18 18"/></svg></button></span></label><p class="form-hint wide-label">Use 8–128 characters. The new password will be shown once after saving.</p><button class="primary wide-label" type="submit">Save new password →</button>`);
  const form=d.querySelector('form');let newPassword='';
  d.addEventListener('close',()=>{newPassword='';});
  form.addEventListener('submit',async event=>{
    event.preventDefault();newPassword=form.elements.password.value;const submit=form.querySelector('[type="submit"]');submit.disabled=true;
    try{
      const result=await request(route,{method:'POST',body:JSON.stringify({password:newPassword})});
      const loginValue=kind==='staff'?result.username:result.email;
      d.querySelector('.dialog-heading .eyebrow').textContent='SHARE SECURELY';d.querySelector('.dialog-heading h2').textContent='Password updated';form.remove();
      const panel=document.createElement('section');panel.className='credential-share';
      const note=document.createElement('p');note.textContent=`Give these login details to ${name}. The password is shown once and is not stored in readable form.`;panel.append(note);
      const loginLine=document.createElement('p');loginLine.textContent=`${loginLabel}: ${loginValue}`;panel.append(loginLine);
      const passwordLine=document.createElement('p');passwordLine.append('New password: ');const passwordText=document.createElement('code');passwordText.textContent=newPassword;passwordLine.append(passwordText);panel.append(passwordLine);
      const copy=document.createElement('button');copy.type='button';copy.className='outline';copy.textContent='Copy login details';copy.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(`${loginLabel}: ${loginValue}\nPassword: ${newPassword}`);toast('Login details copied.');}catch{toast('Please copy the details shown above.');}});panel.append(copy);
      const done=document.createElement('button');done.type='button';done.className='primary';done.textContent='Done';done.addEventListener('click',()=>d.close());panel.append(done);d.querySelector('.dialog-heading').insertAdjacentElement('afterend',panel);
    }catch(error){toast(error.message);submit.disabled=false;}
  });
}
